//go:build amd64

package bitbuffer

import (
	"github.com/thebagchi/asn1c-go/lib/cpu"
)

// How many bytes each assembly kernel handles per iteration.
const (
	BLOCK_SSE2   = 16
	BLOCK_AVX2   = 32
	BLOCK_AVX512 = 64
)

// The three kernels are generated by avo from gen/main.go into shift_amd64.s:
// the generator is ordinary Go, so the assembly is reviewed as the program that
// produced it. The declarations at the end of this file are what Go sees of
// them, and go vet's asmdecl check holds them and the assembly's frames in
// step. Regenerate with "make generate" after editing gen/main.go.
//
//go:generate go run ./gen/main.go -out shift_amd64.s -pkg bitbuffer

// The amd64 kernels. SSE2 is part of the architecture's baseline, so it can
// always run.
var (
	SHIFT_SSE2 = &_Kernel{
		name:  NAME_SSE2,
		block: BLOCK_SSE2,
		have:  true,
		run:   _ShiftBlocksSSE2,
	}
	SHIFT_AVX2 = &_Kernel{
		name:  NAME_AVX2,
		block: BLOCK_AVX2,
		have:  cpu.HAS_AVX2,
		run:   _ShiftBlocksAVX2,
	}
	SHIFT_AVX512 = &_Kernel{
		name:  NAME_AVX512,
		block: BLOCK_AVX512,
		have:  cpu.HAS_AVX512,
		run:   _ShiftBlocksAVX512,
	}
)

// _ShiftKernels lists every kernel amd64 has, narrowest first.
//
// Revisions:
//   - 2026-09-23 03:58: initial creation
//   - 2026-09-24 01:40: begins with the Go kernel, like every architecture
//   - 2026-09-24 01:38: the kernels are named variables, as lib/per's are
func _ShiftKernels() []*_Kernel {
	return []*_Kernel{SHIFT_GO, SHIFT_SSE2, SHIFT_AVX2, SHIFT_AVX512}
}

// _RunShift runs the kernel _Select chose at start-up, called by name rather
// than through its run field.
//
// The choice is made once, in init, and this switches on it - not on the
// feature bits again - so there is one place that decides which kernel runs.
// It is not a call through SHIFT_KERNEL.run because a call through a function
// value makes escape analysis give up on every slice it is passed: that way,
// WriteBytes leaked its argument, and a caller holding its bytes in a stack
// array - lib/per's NumericString encoder does - had that array moved to the
// heap on every call, which cost more at sixteen characters than its kernel
// saved. A direct call to a noescape stub leaks nothing.
//
// Revisions:
//   - 2026-09-23 06:50: initial creation
//   - 2026-09-24 01:10: dispatches on the kernel init selected rather than on
//     the feature bits, so the selection is made in one place
//   - 2026-09-24 01:38: switches on which kernel was selected, not its block
func _RunShift(
	dst,
	src []byte,
	left,
	right uint8,
) {
	switch SHIFT_KERNEL {
	case SHIFT_AVX512:
		_ShiftBlocksAVX512(
			dst,
			src,
			left,
			right,
		)
	case SHIFT_AVX2:
		_ShiftBlocksAVX2(
			dst,
			src,
			left,
			right,
		)
	case SHIFT_SSE2:
		_ShiftBlocksSSE2(
			dst,
			src,
			left,
			right,
		)
	default:
		_ShiftBlocksGo(
			dst,
			src,
			left,
			right,
		)
	}
}

// _ShiftBlocksSSE2 writes dst[i] = src[i]<<left | src[i+1]>>right for every
// byte of dst, sixteen bytes per iteration, in legacy SSE encodings only.
//
// len(src) must be at least len(dst)+1 and len(dst) a multiple of sixteen. It
// is declared noescape so a caller's stack buffer stays where it is.
//
// Revisions:
//   - 2026-09-23 09:10: initial creation, in place of the generated stub
//
//go:noescape
func _ShiftBlocksSSE2(
	dst,
	src []byte,
	left,
	right uint8,
)

// _ShiftBlocksAVX2 is _ShiftBlocksSSE2 at thirty-two bytes per iteration, in
// VEX encodings only, ending in VZEROUPPER.
//
// Revisions:
//   - 2026-09-23 09:10: initial creation, in place of the generated stub
//
//go:noescape
func _ShiftBlocksAVX2(
	dst,
	src []byte,
	left,
	right uint8,
)

// _ShiftBlocksAVX512 is _ShiftBlocksSSE2 at sixty-four bytes per iteration, in
// EVEX encodings only, ending in VZEROUPPER. It needs AVX512BW.
//
// Revisions:
//   - 2026-09-23 09:10: initial creation, in place of the generated stub
//
//go:noescape
func _ShiftBlocksAVX512(
	dst,
	src []byte,
	left,
	right uint8,
)
